package com.oms.order.service;

import com.ruoyi.common.core.constant.SecurityConstants;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.time.LocalDateTime;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** Durable virtual-outbound command; inventory owns atomic consumption and replay receipts. */
@Service
public class OrderVirtualOutboundService {
    @Resource private OrderRepository repository;
    @Resource private OrderShipmentDispatchService locks;
    @Resource private OrderWarehouseClient inventory;
    @Resource private OrderCatalog catalog;
    private String error(RuntimeException e,String fallback){String message=e instanceof IllegalArgumentException?e.getMessage():fallback;if(message==null)message=fallback;return message.substring(0,Math.min(1000,message.length()));}
    private TransactionTemplate tx(){TransactionTemplate tx=new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));tx.setTimeout(120);return tx;}
    private Object canonical(Object value){if(value instanceof Map){Map<String,Object> copy=new TreeMap<>();((Map<?,?>)value).forEach((k,v)->copy.put(k.toString(),canonical(v)));return copy;}if(value instanceof List){List<Object> copy=new ArrayList<>();for(Object item:(List<?>)value)copy.add(canonical(item));return copy;}return value;}
    private String requestId(String company,long shipment,long version){return "VO"+hash(company+"/"+shipment+"/"+version).substring(0,40);}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> items(Map<String,Object> body){require(body.get("items") instanceof List&&!((List<?>)body.get("items")).isEmpty()&&((List<?>)body.get("items")).size()<=20,"每次请选择1至20张发货单");List<Map<String,Object>> result=new ArrayList<>();Set<Long> seen=new HashSet<>();for(Object raw:(List<?>)body.get("items")){require(raw instanceof Map,"出库参数无效");Map<String,Object> item=(Map<String,Object>)raw;require(number(item,"id")>0&&seen.add(number(item,"id"))&&item.containsKey("control_version")&&number(item,"control_version")>=0,"发货单重复或缺少版本");result.add(item);}return result;}
    @SuppressWarnings("unchecked") private void gates(String company,Map<String,Object> shipment){
        Map<String,Object> order=(Map<String,Object>)shipment.get("order"),platform=(Map<String,Object>)shipment.get("platform"),shop=(Map<String,Object>)shipment.get("shop");
        require(shop.get("lease_until")==null||time(text(shop,"lease_until")).isBefore(LocalDateTime.now()),"店铺正在处理，请稍后重试");require("WAIT_ALLOCATION".equals(text(order,"status"))&&"APPROVED".equals(text(order,"review_status")),"来源订单已停止履约或尚未审核");require(number(order,"manual_hold")==0,"来源订单已人工挂起");String block=OrderReviewPolicy.systemBlock(platform);require(block.isEmpty(),block);require(number(platform,"business_order_id")==number(shipment,"order_id")&&"SUCCESS".equals(text(platform,"conversion_status")),"来源订单关联不一致");require("MATCHED".equals(text(shipment,"carrier_match_status"))&&!text(shipment,"carrier_code").isEmpty(),"请先匹配快递");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=?",Long.class,company,shipment.get("id"))==0,"已有WMS下发记录，不能虚拟出库");
        List<Map<String,Object>> stores=catalog.warehouses(company);List<Map<String,Object>> lines=repository.db().query("SELECT store_code FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",ROW,company,shipment.get("id"));require(!lines.isEmpty(),"发货单明细缺失");
        for(Map<String,Object> line:lines){List<Map<String,Object>> matches=new ArrayList<>();for(Map<String,Object> store:stores)if(text(store,"wms_simulation_code").equals(text(line,"store_code"))&&text(store,"owner_code").equals(text(shipment,"owner_code"))&&text(store,"real_store_code").equals(text(shipment,"real_store_code")))matches.add(store);require(matches.size()==1&&number(matches.get(0),"outbound_mode")==2,"发货单全部来源仓须为启用的虚拟出库仓；混合模式或WMS仓不能虚拟出库");}
    }
    @SuppressWarnings("unchecked") private Map<String,Object> payload(String company,Map<String,Object> shipment,Map<String,Object> item,String actor){
        gates(company,shipment);require(Arrays.asList("WAIT_DISPATCH","PART_SHIPPED").contains(text(shipment,"status")),"当前发货单不允许虚拟出库");
        require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=? AND state<>'COMPLETED'",Long.class,company,shipment.get("id"))==0,"已有出库任务待处理，请先核对或重试原任务");
        List<Map<String,Object>> lines=repository.db().query("SELECT * FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=? ORDER BY id FOR UPDATE",ROW,company,shipment.get("id"));require(!lines.isEmpty()&&lines.size()<=500,"发货明细须为1至500行");Map<Long,Long> selected=new HashMap<>();
        if(item.containsKey("lines")){require(item.get("lines") instanceof List&&((List<?>)item.get("lines")).size()<=500,"出库行参数无效");for(Object raw:(List<?>)item.get("lines")){require(raw instanceof Map,"出库行参数无效");Map<String,Object> row=(Map<String,Object>)raw;require(number(row,"id")>0&&number(row,"quantity")>=0&&selected.put(number(row,"id"),number(row,"quantity"))==null,"出库行重复或数量无效");}}
        Map<Long,Map<String,Object>> receipts=new HashMap<>();for(Map<String,Object> r:data(inventory.receipts(company,number(shipment,"channel_id"),text(shipment,"platform_tid"),SecurityConstants.INNER)))require(receipts.put(number(r,"id"),r)==null,"仓库占用回执重复");long total=0,left=0;List<Map<String,Object>> outgoing=new ArrayList<>();Set<Long> allIds=new HashSet<>();
        for(Map<String,Object> line:lines){allIds.add(number(line,"id"));long available=number(line,"quantity")-number(line,"shipped_quantity");require(available>=0,"发货明细累计出库异常");left+=available;long take=item.containsKey("lines")?selected.getOrDefault(number(line,"id"),0L):available;if(take==0)continue;require(take>0&&take<=available,"出库数量超过发货行剩余数量");Map<String,Object> r=receipts.get(number(line,"allocation_id"));require(r!=null,"出库占用来源缺失或已释放");for(String field:Arrays.asList("sku_sn","platform_oid","store_code","source_type"))require(text(line,field).equals(text(r,field)),"出库来源身份不一致");for(String field:Arrays.asList("quantity","batch_id","stock_source_id"))require(number(line,field)==number(r,field),"出库数量、批次或来源不一致");require(text(shipment,"owner_code").equals(text(r,"owner_code"))&&text(shipment,"real_store_code").equals(text(r,"real_store_code"))&&number(line,"shipped_quantity")==number(r,"outbound_quantity"),"库存与发货单累计出库或归属不一致，请先核对原回执");Map<String,Object> out=new LinkedHashMap<>();for(String field:Arrays.asList("id","allocation_id","sku_sn","platform_oid","store_code","source_type","batch_id","stock_source_id"))out.put(field,line.get(field));out.put("owner_code",shipment.get("owner_code"));out.put("real_store_code",shipment.get("real_store_code"));out.put("outbound_before",line.get("shipped_quantity"));out.put("quantity",take);outgoing.add(out);total+=take;}
        require(allIds.containsAll(selected.keySet()),"出库行不属于该发货单");require(total>0,"请填写至少一件出库数量");if(total<left){Map<String,Object> order=(Map<String,Object>)shipment.get("order");try{require(JSON.readTree(text(order,"allocation_policy")).path("allow_partial").asInt()==1,"店铺分仓规则未允许部分发货，只能全部出库");}catch(java.io.IOException e){throw new IllegalArgumentException("分仓规则快照无效");}}
        Map<String,Object> p=new LinkedHashMap<>();p.put("request_id",requestId(company,number(shipment,"id"),number(item,"control_version")));p.put("shipment_sn",shipment.get("shipment_sn"));p.put("channel_id",shipment.get("channel_id"));p.put("platform_tid",shipment.get("platform_tid"));p.put("quantity",total);p.put("lines",outgoing);p.put("operator_name",actor);p.put("input",canonical(item));return p;
    }
    private Map<String,Object> result(long id,boolean success,String message){Map<String,Object> r=new LinkedHashMap<>();r.put("id",id);r.put("success",success);r.put("message",message);return r;}
    public List<Map<String,Object>> preview(String company,Map<String,Object> body){List<Map<String,Object>> results=new ArrayList<>();for(Map<String,Object> item:items(body)){long id=number(item,"id");try{results.add(tx().execute(s->{Map<String,Object> shipment=locks.lock(company,id,number(item,"control_version"),false);Map<String,Object> p=payload(company,shipment,item,"出库预览");Map<String,Object> r=result(id,true,"虚拟出库，库存确认后更新已发货数量");r.put("quantity",p.get("quantity"));r.put("lines",p.get("lines"));return r;}));}catch(RuntimeException e){results.add(result(id,false,error(e,"出库条件暂未确认，请刷新重试")));}}return results;}
    @SuppressWarnings("unchecked") public List<Map<String,Object>> submit(String company,Map<String,Object> body,String actor){List<Map<String,Object>> results=new ArrayList<>();for(Map<String,Object> item:items(body)){long id=number(item,"id");try{results.add(tx().execute(s->{Map<String,Object> shipment=locks.lock(company,id,null,false);String request=requestId(company,id,number(item,"control_version"));List<Map<String,Object>> old=repository.db().query("SELECT * FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND request_id=? FOR UPDATE",ROW,company,request);if(!old.isEmpty()){Map<String,Object> p=decode(old.get(0));require(encode(p.get("input")).equals(encode(canonical(item))),"相同出库请求的数量或行参数发生变化");return result(id,true,"该出库请求已提交，请刷新核对处理结果");}require(number(shipment,"control_version")==number(item,"control_version"),"发货单已变化，请刷新后重试");Map<String,Object> p=payload(company,shipment,item,actor);String json=encode(canonical(p));require(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=900000,"出库指令超过限制");repository.db().update("INSERT INTO oms_order_shipment_virtual_outbound(company_code,shipment_id,shipment_sn,request_id,payload_json,payload_hash,quantity,created_by) VALUES (?,?,?,?,?,?,?,?)",company,id,shipment.get("shipment_sn"),request,json,hash(json),p.get("quantity"),actor);freeze(company,shipment);log(company,shipment,"VIRTUAL_OUTBOUND_SUBMIT","SUCCESS","提交虚拟出库 "+p.get("quantity")+" 件；等待库存记账确认",actor);return result(id,true,"已提交虚拟出库，等待库存确认");}));}catch(RuntimeException e){results.add(result(id,false,error(e,"出库提交未确认，请刷新核对原任务")));}}return results;}
    private void freeze(String company,Map<String,Object> shipment){repository.db().update("UPDATE oms_order_shipment SET status='DISPATCHING',control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("id"));repository.db().update("UPDATE oms_order SET control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("order_id"));}
    private void log(String company,Map<String,Object> shipment,String action,String result,String message,String actor){repository.db().update("INSERT INTO oms_order_shipment_log(company_code,shipment_id,action,result,message,operator_name) VALUES (?,?,?,?,?,?)",company,shipment.get("id"),action,result,message,actor);repository.log(company,number(shipment,"platform_order_id"),action,result,text(shipment,"shipment_sn")+"："+message,actor);}
    @SuppressWarnings("unchecked") private Map<String,Object> decode(Map<String,Object> task){require(hash(text(task,"payload_json")).equals(text(task,"payload_hash")),"虚拟出库快照校验失败");try{return JSON.readValue(text(task,"payload_json"),Map.class);}catch(Exception e){throw new IllegalArgumentException("虚拟出库快照损坏");}}
    public Map<String,Object> retry(String company,long id,long version,String actor){return tx().execute(s->{Map<String,Object> shipment=locks.lock(company,id,version,false);gates(company,shipment);Map<String,Object> task=repository.db().query("SELECT * FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE",ROW,company,id).stream().findFirst().orElseThrow(()->new IllegalArgumentException("没有虚拟出库任务"));require("FAILED".equals(text(task,"state")),"仅明确失败可以重试；结果未确认时请核对原任务");decode(task);repository.db().update("UPDATE oms_order_shipment_virtual_outbound SET state='PENDING',last_error='',next_attempt=NOW() WHERE company_code=? AND id=?",company,task.get("id"));freeze(company,shipment);log(company,shipment,"VIRTUAL_OUTBOUND_RETRY","SUCCESS","按原虚拟出库快照重试",actor);return result(id,true,"已提交原虚拟出库任务重试");});}
    public Map<String,Object> reconcile(String company,long id,String actor){return tx().execute(s->{Map<String,Object> shipment=locks.lock(company,id,null,false);List<Map<String,Object>> tasks=repository.db().query("SELECT * FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE",ROW,company,id);require(!tasks.isEmpty(),"尚无虚拟出库任务");Map<String,Object> task=tasks.get(0);if("COMPLETED".equals(text(task,"state")))return result(id,true,"虚拟出库已完成");try{Map<String,Object> reply=data(inventory.virtualReceipt(company,text(task,"request_id"),SecurityConstants.INNER));if("COMPLETED".equals(text(reply,"state"))){sync(company,shipment,task,reply,actor);return result(id,true,"原虚拟出库已确认，发货数量已更新");}return result(id,false,"库存尚无已提交的出库回执，未重新记账；请刷新核对原任务");}catch(RuntimeException e){return result(id,false,error(e,"库存回执暂未确认，请稍后核对"));}});}
    /** Queries before every post, including after a lost reply or source hold/configuration change. */
    public void process(String company,long id){tx().execute(s->{Map<String,Object> shipment=locks.lock(company,id,null,false);List<Map<String,Object>> tasks=repository.db().query("SELECT * FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=? AND state IN ('PENDING','UNKNOWN') AND next_attempt<=NOW() ORDER BY id LIMIT 1 FOR UPDATE",ROW,company,id);if(tasks.isEmpty())return null;Map<String,Object> task=tasks.get(0);boolean posting=false;try{Map<String,Object> p=decode(task);Map<String,Object> reply=data(inventory.virtualReceipt(company,text(task,"request_id"),SecurityConstants.INNER));if(!"COMPLETED".equals(text(reply,"state"))){require("MISSING".equals(text(reply,"state")),"库存回执状态不明确");try{gates(company,shipment);}catch(RuntimeException gate){repository.db().update("UPDATE oms_order_shipment_virtual_outbound SET last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND) WHERE company_code=? AND id=?",error(gate,"暂不允许虚拟出库"),company,task.get("id"));return null;}repository.db().update("UPDATE oms_order_shipment_virtual_outbound SET attempts=attempts+1 WHERE company_code=? AND id=?",company,task.get("id"));posting=true;R<Map<String,Object>> response=inventory.virtualOutbound(company,p,SecurityConstants.INNER);if(response!=null&&!R.isSuccess(response)){repository.db().update("UPDATE oms_order_shipment_virtual_outbound SET state='FAILED',last_error=? WHERE company_code=? AND id=?",response.getMsg(),company,task.get("id"));restore(company,shipment);log(company,shipment,"VIRTUAL_OUTBOUND_RESULT","FAILED",error(new IllegalArgumentException(response.getMsg()),"库存明确拒绝出库"),"出库任务");return null;}reply=data(response);}sync(company,shipment,task,reply,"出库任务");}catch(RuntimeException e){repository.db().update("UPDATE oms_order_shipment_virtual_outbound SET state=?,last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND) WHERE company_code=? AND id=?",posting||"UNKNOWN".equals(text(task,"state"))?"UNKNOWN":"PENDING",error(e,"虚拟出库结果未确认，将按原请求核对库存回执"),company,task.get("id"));}return null;});}
    private void restore(String company,Map<String,Object> shipment){long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",Long.class,company,shipment.get("id"));repository.db().update("UPDATE oms_order_shipment SET status=?,control_version=control_version+1 WHERE company_code=? AND id=?",shipped>0?"PART_SHIPPED":"WAIT_DISPATCH",company,shipment.get("id"));repository.db().update("UPDATE oms_order SET control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("order_id"));}
    private void sync(String company,Map<String,Object> shipment,Map<String,Object> task,Map<String,Object> reply,String actor){TransactionTemplate nested=tx();nested.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);nested.execute(s->{applySync(company,shipment,task,reply,actor);return null;});}
    @SuppressWarnings("unchecked") private void applySync(String company,Map<String,Object> shipment,Map<String,Object> task,Map<String,Object> reply,String actor){Map<String,Object> p=decode(task);require("COMPLETED".equals(text(reply,"state"))&&text(reply,"request_id").equals(text(task,"request_id"))&&text(reply,"shipment_sn").equals(text(shipment,"shipment_sn"))&&number(reply,"quantity")==number(task,"quantity"),"库存出库回执身份或数量不一致");require(reply.get("lines") instanceof List&&p.get("lines") instanceof List,"出库回执行缺失");Map<Long,Map<String,Object>> expected=new HashMap<>();for(Map<String,Object> line:(List<Map<String,Object>>)p.get("lines"))expected.put(number(line,"allocation_id"),line);Set<Long> seen=new HashSet<>();for(Object raw:(List<?>)reply.get("lines")){require(raw instanceof Map,"出库回执行无效");Map<String,Object> line=(Map<String,Object>)raw,old=expected.get(number(line,"allocation_id"));require(old!=null&&seen.add(number(line,"allocation_id")),"库存回执行重复或不属于原指令");for(String field:Arrays.asList("sku_sn","platform_oid","store_code","source_type","owner_code","real_store_code"))require(text(old,field).equals(text(line,field)),"库存出库回执行身份不一致");for(String field:Arrays.asList("id","batch_id","stock_source_id","quantity","outbound_before"))require(number(old,field)==number(line,field),"库存出库回执行数量或来源不一致");require(number(line,"outbound_quantity")==number(old,"outbound_before")+number(old,"quantity"),"累计出库回执数量不一致");require(repository.db().update("UPDATE oms_order_shipment_line SET shipped_quantity=? WHERE company_code=? AND shipment_id=? AND id=? AND shipped_quantity=? AND quantity>=?",line.get("outbound_quantity"),company,shipment.get("id"),old.get("id"),old.get("outbound_before"),line.get("outbound_quantity"))==1,"发货行出库进度已变化，需核对原回执");}require(seen.size()==expected.size(),"库存出库回执行不完整");long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",Long.class,company,shipment.get("id"));require(shipped<=number(shipment,"quantity"),"累计出库超过发货单数量");repository.db().update("UPDATE oms_order_shipment SET status=?,control_version=control_version+1 WHERE company_code=? AND id=?",shipped==number(shipment,"quantity")?"SHIPPED":"PART_SHIPPED",company,shipment.get("id"));new OrderShipmentOutboundRecords(repository).virtual(company,shipment,p,actor);repository.db().update("UPDATE oms_order_shipment_virtual_outbound SET state='COMPLETED',last_error='',completed_at=NOW() WHERE company_code=? AND id=?",company,task.get("id"));repository.db().update("UPDATE oms_order SET control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("order_id"));log(company,shipment,"VIRTUAL_OUTBOUND_RESULT","SUCCESS","虚拟出库确认 "+task.get("quantity")+" 件；本发货单累计已发货 "+shipped+" 件",actor);}
}
